#!/bin/bash
# al_build.sh GENDIR TAG OLEANDIR JOBS [K|A|ALL] [SHARD NSHARDS]
# Compile the modules generated by scripts/gen_al.py (GENDIR/ALGen/TAG/modules.txt) with `lean -o`
# into OLEANDIR. Run from the repository root; the assembly needs `lake build Collatz.LongStopAL`.
#   K: only the chunk modules K* (optionally only shard SHARD of NSHARDS, balanced by work);
#   A: the assembly modules A* and Final, in dependency order (all K oleans must be present);
#   ALL: both. JOBS lean processes run in parallel (each up to ~4 GB).
set -euo pipefail
GEN=$1; TAG=$2; OUT=$3; JOBS=$4; WHAT=${5:-ALL}; SHARD=${6:-0}; NSH=${7:-1}
LIST=$GEN/ALGen/$TAG/modules.txt
mkdir -p "$OUT/ALGen/$TAG"
# AL_LEAN_PATH (e.g. a directory holding Collatz/LSA/Basic.olean) avoids `lake env` for the
# Mathlib-free chunk modules; the assembly needs the full library path from `lake env`.
if [ -n "${AL_LEAN_PATH:-}" ]; then export LEAN_PATH="$AL_LEAN_PATH:$OUT"
else export LEAN_PATH="$(lake env printenv LEAN_PATH):$OUT"; fi
src() { echo "$GEN/$(echo "$1" | tr . /).lean"; }
obj() { echo "$OUT/$(echo "$1" | tr . /).olean"; }
export -f src obj; export GEN OUT
comp() { lean -R "$GEN" -o "$(obj "$1")" "$(src "$1")" > "$(obj "$1").log" 2>&1 || { cat "$(obj "$1").log"; echo "FAILED $1"; return 1; }; }
export -f comp
if [ "$WHAT" = K ] || [ "$WHAT" = ALL ]; then
  # longest-processing-time assignment of the K modules to NSH shards (deterministic)
  grep -E '^[^ ]*\.K[0-9]+ ' "$LIST" | sort -k2,2nr -k1,1 | awk -v n="$NSH" -v s="$SHARD" '
    { best = 0; for (i = 1; i < n; i++) if (load[i] < load[best]) best = i;
      load[best] += $2 + 1000000; if (best == s) print $1 }' > "$OUT/mine-$TAG.txt"
  echo "$(wc -l < "$OUT/mine-$TAG.txt") chunk modules"
  xargs -P "$JOBS" -I{} bash -c 'comp {}' < "$OUT/mine-$TAG.txt" || { echo "chunk modules failed"; exit 1; }
  while read -r m; do test -s "$(obj "$m")"; done < "$OUT/mine-$TAG.txt"
fi
if [ "$WHAT" = A ] || [ "$WHAT" = ALL ]; then
  grep -E '^[^ ]*\.K[0-9]+ ' "$LIST" | while read -r m _; do
    test -s "$(obj "$m")" || { echo "missing $m"; exit 1; }; done
  # assembly modules level by level: a module is ready when all its imports are compiled
  grep -vE '^[^ ]*\.K[0-9]+ ' "$LIST" > "$OUT/asm-$TAG.txt"
  while [ -s "$OUT/asm-$TAG.txt" ]; do
    : > "$OUT/ready-$TAG.txt"; : > "$OUT/rest-$TAG.txt"
    while read -r m w imps; do
      ok=1; for i in $imps; do case $i in ALGen.*) test -s "$(obj "$i")" || ok=0;; esac; done
      if [ $ok = 1 ]; then echo "$m" >> "$OUT/ready-$TAG.txt"; else echo "$m $w $imps" >> "$OUT/rest-$TAG.txt"; fi
    done < "$OUT/asm-$TAG.txt"
    test -s "$OUT/ready-$TAG.txt" || { echo "assembly stuck"; exit 1; }
    xargs -P "$JOBS" -I{} bash -c 'comp {}' < "$OUT/ready-$TAG.txt" || { echo "assembly failed"; exit 1; }
    mv "$OUT/rest-$TAG.txt" "$OUT/asm-$TAG.txt"
  done
  cat "$(obj ALGen.$TAG.Final).log"
  echo "AL assembly for $TAG passed (axiom audit included)"
fi
